def exhaust_private_fds(soft):
    if type(soft) is not int or not 24<=soft<=64:raise ValueError('24..64 private fd limit')
    code="""import os,sys,resource,json
old=resource.getrlimit(resource.RLIMIT_NOFILE);soft=int(sys.argv[1])
if old[1]!=resource.RLIM_INFINITY and soft>old[1]:raise RuntimeError('private hard limit too small')
opened=[];error=0
try:
