 during=resource.getrlimit(resource.RLIMIT_NOFILE)
 for _ in range(128):
  try:opened.append(os.open('/dev/null',os.O_RDONLY))
  except OSError as exc:error=exc.errno;break
finally:
 for fd in opened:os.close(fd)
 resource.setrlimit(resource.RLIMIT_NOFILE,old)
print(json.dumps({'soft':during[0],'hard':during[1],'old_hard':old[1],'opened':len(opened),'errno':error,'restored':resource.getrlimit(resource.RLIMIT_NOFILE)==old,'pid':os.getpid()}))
